+    private String statusOf(MacroSnapshotResult snapshot, String indicatorId) {
+        return snapshot.indicators().stream()
+                .filter(i -> i.indicatorId().equals(indicatorId))
+                .findFirst()
+                .orElseThrow()
+                .status();
+    }
