+    private MacroSnapshotResult.ObservationValue valueOf(
+            MacroSnapshotResult snapshot, String indicatorId) {
+        return snapshot.indicators().stream()
+                .filter(i -> i.indicatorId().equals(indicatorId))
+                .findFirst()
+                .orElseThrow()
+                .latest();
+    }
